    public ListNode removeNthFromEnd(ListNode head, int n) {
        // 创建一个新的哑节点，指向原链表头  
        ListNode s = new ListNode(-1, head);
        // 递归调用remove方法，从哑节点开始进行删除操作  
        remove(s, n);
        // 返回新链表的头（去掉可能的哑节点）  
        return s.next;
    }

    public int remove(ListNode p, int n) {
        // 递归结束条件：如果当前节点为空，返回0  
        if (p == null) {
            return 0;
        }
        // 递归深入到下一个节点  
        int net = remove(p.next, n);
        // 如果当前节点是倒数第n个节点，进行删除操作  
        if (net == n) {
            p.next = p.next.next;  
        }
        // 返回当前节点的总深度  
        return net + 1;
    }
}
